1	package wslenv
2	
3	import (
4		"context"
5		"errors"
6		"net/netip"
7		"slices"
8		"strings"
9		"testing"
10	)
11	
12	const (
13		wslRelease    = "6.18.33.2-microsoft-standard-WSL2\n"
14		nativeRelease = "6.12.0-amd64\n"
15		osreleasePath = "/proc/sys/kernel/osrelease"
16		routePath     = "/proc/net/route"
17	)
18	
19	// fakeProbe records every call so a test can assert what was (not) read.
20	type fakeProbe struct {
21		goos      string
22		env       map[string]string
23		files     map[string][]byte
24		fileErr   map[string]error
25		ifaces    []string
26		ifaceErr  error
27		mode      string
28		modeErr   error
29		reads     []string
30		getenvs   []string
31		ifaceN    int
32		modeCalls int
33	}
34	
35	func (f *fakeProbe) probe() Probe {
36		return Probe{
37			GOOS:   f.goos,
38			Getenv: func(k string) string { f.getenvs = append(f.getenvs, k); return f.env[k] },
39			ReadFile: func(p string) ([]byte, error) {
40				f.reads = append(f.reads, p)
41				if err := f.fileErr[p]; err != nil {
42					return nil, err
43				}
44				return f.files[p], nil
45			},
46			InterfaceNames: func() ([]string, error) { f.ifaceN++; return f.ifaces, f.ifaceErr },
47			NetworkingMode: func(ctx context.Context) (string, error) {
48				f.modeCalls++
49				if err := ctx.Err(); err != nil {
50					return "", err
51				}
52				return f.mode, f.modeErr
53			},
54		}
55	}
56	
57	func (f *fakeProbe) read(path string) bool { return slices.Contains(f.reads, path) }
58	
59	func wslFake() *fakeProbe {
60		return &fakeProbe{
61			goos:   "linux",
62			env:    map[string]string{"WSL_DISTRO_NAME": "archlinux"},
63			files:  map[string][]byte{osreleasePath: []byte(wslRelease), routePath: []byte(natRoutes)},
64			ifaces: []string{"lo", "eth0"},
65			mode:   "nat",
66		}
67	}
68	
69	func TestGatherNotLinuxProbesNothing(t *testing.T) {
70		for _, goos := range []string{"windows", "darwin", ""} {
71			f := wslFake()
72			f.goos = goos
73			got := Gather(context.Background(), f.probe())
74			if got.DistroName != "" || got.OSRelease != "" || got.NetworkingMode != "" ||
75				got.NetworkingModeErr != nil || len(got.Interfaces) != 0 || len(got.ProcNetRoute) != 0 {
76				t.Errorf("GOOS=%q: Facts = %+v, want empty", goos, got)
77			}
78			if len(f.reads)+len(f.getenvs)+f.ifaceN+f.modeCalls != 0 {
79				t.Errorf("GOOS=%q: probe called (reads=%v getenv=%v ifaces=%d mode=%d)", goos, f.reads, f.getenvs, f.ifaceN, f.modeCalls)
80			}
81		}
82	}
83	
84	func TestGatherNativeLinuxSkipsWSLReads(t *testing.T) {
85		f := wslFake()
86		f.env = map[string]string{}
87		f.files[osreleasePath] = []byte(nativeRelease)
88		got := Gather(context.Background(), f.probe())
89		if !f.read(osreleasePath) {
90			t.Errorf("osrelease not read: reads=%v", f.reads)
91		}
92		if f.modeCalls != 0 {
93			t.Errorf("NetworkingMode called %d times on native Linux", f.modeCalls)
94		}
95		if f.read(routePath) {
96			t.Errorf("%s read on native Linux", routePath)
97		}
98		if got.NetworkingMode != "" || got.NetworkingModeErr != nil || len(got.ProcNetRoute) != 0 {
99			t.Errorf("Facts = %+v, want no WSL facts", got)
100		}
101		if !strings.Contains(got.OSRelease, "6.12.0-amd64") {
102			t.Errorf("OSRelease = %q", got.OSRelease)
103		}
104		if Classify(got) != (Info{}) {
105			t.Errorf("Classify = %+v, want zero", Classify(got))
106		}
107	}
108	
109	func TestGatherWSLSignals(t *testing.T) {
110		tests := []struct {
111			name    string
112			env     map[string]string
113			release string
114		}{
115			{"distro name", map[string]string{"WSL_DISTRO_NAME": "archlinux"}, wslRelease},
116			{"osrelease only (env -i)", map[string]string{}, wslRelease},
117			{"distro name, plain osrelease", map[string]string{"WSL_DISTRO_NAME": "Ubuntu"}, nativeRelease},
118		}
119		for _, tt := range tests {
120			t.Run(tt.name, func(t *testing.T) {
121				f := wslFake()
122				f.env = tt.env
123				f.files[osreleasePath] = []byte(tt.release)
124				got := Gather(context.Background(), f.probe())
125				if f.modeCalls != 1 {
126					t.Errorf("NetworkingMode calls = %d, want 1", f.modeCalls)
127				}
128				if !f.read(osreleasePath) || !f.read(routePath) {
129					t.Errorf("reads = %v, want osrelease and route", f.reads)
130				}
131				if f.ifaceN != 1 {
132					t.Errorf("InterfaceNames calls = %d, want 1", f.ifaceN)
133				}
134				if got.DistroName != tt.env["WSL_DISTRO_NAME"] {
135					t.Errorf("DistroName = %q", got.DistroName)
136				}
137				if strings.TrimSpace(got.OSRelease) != strings.TrimSpace(tt.release) {
138					t.Errorf("OSRelease = %q", got.OSRelease)
139				}
140				if got.NetworkingMode != "nat" || got.NetworkingModeErr != nil {
141					t.Errorf("mode = %q err = %v", got.NetworkingMode, got.NetworkingModeErr)
142				}
143				if strings.Join(got.Interfaces, ",") != "lo,eth0" {
144					t.Errorf("Interfaces = %v", got.Interfaces)
145				}
146				if string(got.ProcNetRoute) != natRoutes {
147					t.Errorf("ProcNetRoute = %q", got.ProcNetRoute)
148				}
149			})
150		}
151	}
152	
153	func TestGatherEndToEndClassify(t *testing.T) {
154		f := wslFake()
155		got := Classify(Gather(context.Background(), f.probe()))
156		want := Info{WSL2: true, Mode: ModeNAT, NATInterface: "eth0", NATGateway: netip.MustParseAddr("172.27.128.1")}
157		if got != want {
158			t.Errorf("Classify(Gather) = %+v, want %+v", got, want)
159		}
160	}
161	
162	func TestGatherReadErrorsGiveEmptyValues(t *testing.T) {
163		boom := errors.New("boom")
164	
165		f := wslFake()
166		f.fileErr = map[string]error{osreleasePath: boom}
167		got := Gather(context.Background(), f.probe())
168		if got.OSRelease != "" {
169			t.Errorf("OSRelease = %q on read error, want empty", got.OSRelease)
170		}
171		if got.DistroName != "archlinux" {
172			t.Errorf("DistroName = %q, want archlinux (env still identifies WSL)", got.DistroName)
173		}
174	
175		f = wslFake()
176		f.fileErr = map[string]error{routePath: boom}
177		f.files[routePath] = []byte("partial")
178		got = Gather(context.Background(), f.probe())
179		if len(got.ProcNetRoute) != 0 {
180			t.Errorf("ProcNetRoute = %q on read error, want empty", got.ProcNetRoute)
181		}
182		if got.NetworkingMode != "nat" {
183			t.Errorf("a route read error must not affect the mode: %q", got.NetworkingMode)
184		}
185	
186		f = wslFake()
187		f.ifaceErr = boom
188		f.ifaces = []string{"lo"}
189		got = Gather(context.Background(), f.probe())
190		if len(got.Interfaces) != 0 {
191			t.Errorf("Interfaces = %v on error, want empty", got.Interfaces)
192		}
193	}
194	
195	func TestGatherNetworkingModeError(t *testing.T) {
196		f := wslFake()
197		f.modeErr = errors.New("exec: wslinfo: not found")
198		got := Gather(context.Background(), f.probe())
199		if got.NetworkingModeErr == nil {
200			t.Fatal("NetworkingModeErr = nil, want the probe error")
