3	import (
4		"context"
5		"net"
6		"os"
7		"runtime"
8	)
9	
10	const (
11		osReleasePath = "/proc/sys/kernel/osrelease"
12		procRoutePath = "/proc/net/route"
13	)
14	
15	// Probe is the set of system reads Gather performs. Tests replace every field.
16	type Probe struct {
17		GOOS           string
18		Getenv         func(string) string
19		ReadFile       func(string) ([]byte, error)
20		InterfaceNames func() ([]string, error)
21		NetworkingMode func(ctx context.Context) (string, error)
22	}
23	
24	// SystemProbe returns the Probe backed by the real system.
25	func SystemProbe() Probe {
26		return Probe{
27			GOOS:           runtime.GOOS,
28			Getenv:         os.Getenv,
29			ReadFile:       os.ReadFile,
30			InterfaceNames: interfaceNames,
31			NetworkingMode: wslinfoNetworkingMode,
32		}
33	}
34	
35	// interfaceNames lists the names of this machine's network interfaces.
36	func interfaceNames() ([]string, error) {
37		ifaces, err := net.Interfaces()
38		if err != nil {
39			return nil, err
40		}
41		names := make([]string, 0, len(ifaces))
42		for _, i := range ifaces {
43			names = append(names, i.Name)
44		}
45		return names, nil
46	}
47	
48	// Gather collects Facts through p. It reads nothing off Linux, and reads the
49	// WSL-only facts (interfaces, routes, networking mode) only under WSL. A read
50	// error leaves the matching fact empty.
51	func Gather(ctx context.Context, p Probe) Facts {
52		if p.GOOS != "linux" {
53			return Facts{}
54		}
55		f := Facts{DistroName: p.Getenv("WSL_DISTRO_NAME")}
56		if b, err := p.ReadFile(osReleasePath); err == nil {
57			f.OSRelease = string(b)
58		}
59		if !isWSL(f) {
60			return f
61		}
62		if names, err := p.InterfaceNames(); err == nil {
63			f.Interfaces = names
64		}
65		if b, err := p.ReadFile(procRoutePath); err == nil {
66			f.ProcNetRoute = b
67		}
68		// A probe that ignores ctx must still report a cancelled context.
69		if err := ctx.Err(); err != nil {
70			f.NetworkingModeErr = err
71			return f
72		}
73		f.NetworkingMode, f.NetworkingModeErr = p.NetworkingMode(ctx)
74		return f
75	}
76	
77	// Detect is Classify(Gather(ctx, SystemProbe())).
78	func Detect(ctx context.Context) Info { return Classify(Gather(ctx, SystemProbe())) }
