1	package wslenv
2	
3	import (
4		"context"
5		"errors"
6		"io"
7		"os"
8		"os/exec"
9		"strings"
10		"time"
11	)
12	
13	const (
14		// wslinfoTimeout bounds the child process.
15		wslinfoTimeout = 2 * time.Second
16		// wslinfoMaxOutput bounds what is read from the child and returned.
17		wslinfoMaxOutput = 64
18	)
19	
20	// wslinfoNetworkingMode runs `wslinfo --networking-mode` and returns its
21	// cleaned output. The binary is looked up at two fixed absolute paths (never
22	// through PATH) and runs with an empty environment.
23	func wslinfoNetworkingMode(ctx context.Context) (string, error) {
24		path, err := findWslinfo()
25		if err != nil {
26			return "", err
27		}
28		ctx, cancel := context.WithTimeout(ctx, wslinfoTimeout)
29		defer cancel()
30		cmd := exec.CommandContext(ctx, path, "--networking-mode")
31		cmd.Env = []string{}
32		stdout, err := cmd.StdoutPipe()
33		if err != nil {
34			return "", err
35		}
36		if err := cmd.Start(); err != nil {
37			return "", err
38		}
39		out, readErr := io.ReadAll(io.LimitReader(stdout, wslinfoMaxOutput))
40		waitErr := cmd.Wait()
41		if readErr != nil {
42			return "", readErr
43		}
44		if waitErr != nil {
45			return "", waitErr
46		}
47		return parseWslinfoOutput(out), nil
48	}
49	
50	// findWslinfo returns the first wslinfo binary that exists.
51	func findWslinfo() (string, error) {
52		for _, p := range []string{"/usr/bin/wslinfo", "/usr/sbin/wslinfo"} {
53			if _, err := os.Stat(p); err == nil {
54				return p, nil
55			}
56		}
57		return "", errors.New("wslinfo not found")
58	}
59	
60	// parseWslinfoOutput bounds and cleans the output of `wslinfo --networking-mode`.
61	func parseWslinfoOutput(out []byte) string {
62		s := strings.TrimSpace(string(out))
63		if len(s) > wslinfoMaxOutput {
64			s = s[:wslinfoMaxOutput]
65		}
66		return s
67	}
