1	package wslenv
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"sort"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// The detection reads files and runs one fixed program. It must never reach
16	// the network, and the only child process is wslinfo, started from wslinfo.go
17	// by absolute path. The guard reads every non-test .go file whatever its build
18	// constraints (go/parser does not evaluate them).
19	
20	const wslinfoFile = "wslinfo.go"
21	
22	// networkImports are packages that must not be imported at all.
23	var networkImports = map[string]bool{
24		"net/http": true, "net/rpc": true, "net/smtp": true, "net/textproto": true,
25		"net/http/httputil": true, "crypto/tls": true,
26		"github.com/libp2p/go-netroute": true,
27	}
28	
29	// bannedNetSymbols are the symbols of "net" that open a connection or resolve
30	// a name. Interface enumeration (net.Interfaces) stays allowed.
31	var bannedNetSymbols = map[string]bool{
32		"Dial": true, "DialTimeout": true, "Dialer": true, "Listen": true, "ListenPacket": true,
33		"ListenConfig": true, "ListenTCP": true, "ListenUDP": true, "DialTCP": true, "DialUDP": true,
34		"DialIP": true, "Resolver": true, "DefaultResolver": true, "LookupHost": true, "LookupIP": true,
35		"LookupAddr": true, "LookupCNAME": true, "LookupPort": true, "LookupTXT": true, "LookupMX": true,
36		"LookupNS": true, "LookupSRV": true, "ResolveTCPAddr": true, "ResolveUDPAddr": true, "ResolveIPAddr": true,
37	}
38	
39	type fileFacts struct {
40		imports  map[string]string // local name -> path
41		literals []string          // string literals, in source order
42		selects  []string          // "path.Sym" selector expressions on imported packages
43		offences []string
44	}
45	
46	func scan(fset *token.FileSet, name string, src any) (*fileFacts, error) {
47		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
48		if err != nil {
49			return nil, err
50		}
51		ff := &fileFacts{imports: map[string]string{}}
52		for _, imp := range file.Imports {
53			path, _ := strconv.Unquote(imp.Path.Value)
54			local := path[strings.LastIndex(path, "/")+1:]
55			if imp.Name != nil {
56				local = imp.Name.Name
57				if local == "." {
58					ff.offences = append(ff.offences, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
59				}
60			}
61			ff.imports[local] = path
62			if networkImports[path] || strings.HasPrefix(path, "golang.org/x/net") {
63				ff.offences = append(ff.offences, fmt.Sprintf("%s: network import %s", fset.Position(imp.Pos()), path))
64			}
65		}
66		ast.Inspect(file, func(n ast.Node) bool {
67			switch x := n.(type) {
68			case *ast.BasicLit:
69				if x.Kind == token.STRING {
70					s, _ := strconv.Unquote(x.Value)
71					ff.literals = append(ff.literals, s)
72				}
73			case *ast.SelectorExpr:
74				id, ok := x.X.(*ast.Ident)
75				if !ok {
76					return true
77				}
78				path, ok := ff.imports[id.Name]
79				if !ok {
80					return true
81				}
82				ff.selects = append(ff.selects, path+"."+x.Sel.Name)
83				if path == "net" && bannedNetSymbols[x.Sel.Name] {
84					ff.offences = append(ff.offences, fmt.Sprintf("%s: use of net.%s", fset.Position(x.Pos()), x.Sel.Name))
85				}
86			}
87			return true
88		})
89		return ff, nil
90	}
91	
92	func (ff *fileFacts) importsPath(path string) bool {
93		for _, p := range ff.imports {
94			if p == path {
95				return true
96			}
97		}
98		return false
99	}
100	
101	// wslinfoOffences checks the one file allowed to start a process.
102	func wslinfoOffences(ff *fileFacts) []string {
103		var out []string
104		if !ff.importsPath("os/exec") {
105			out = append(out, wslinfoFile+": does not import os/exec")
106		}
107		var paths []string
108		for _, l := range ff.literals {
109			if strings.HasPrefix(l, "/") {
110				paths = append(paths, l)
111			}
112		}
113		if got, want := strings.Join(paths, " "), "/usr/bin/wslinfo /usr/sbin/wslinfo"; got != want {
114			out = append(out, fmt.Sprintf("%s: absolute path literals are %q, want exactly %q in that order", wslinfoFile, got, want))
115		}
116		hasArg := false
117		for _, l := range ff.literals {
118			if l == "--networking-mode" {
119				hasArg = true
120			}
121			if strings.Contains(l, "PATH") {
122				out = append(out, fmt.Sprintf("%s: literal %q reads PATH", wslinfoFile, l))
123			}
124		}
125		if !hasArg {
126			out = append(out, wslinfoFile+": constant argument --networking-mode not found")
127		}
128		for _, s := range ff.selects {
129			switch s {
130			case "os/exec.LookPath", "os.Getenv", "os.LookupEnv", "os.Environ":
131				out = append(out, fmt.Sprintf("%s: use of %s (no PATH lookup)", wslinfoFile, s))
132			}
133		}
134		return out
135	}
