137	func TestGuardScanFlagsOffences(t *testing.T) {
138		for _, c := range []struct {
139			name, src string
140			want      int
141		}{
142			{"http.go", "package x\nimport \"net/http\"\nvar _ = http.Get\n", 1},
143			{"xnet.go", "package x\nimport \"golang.org/x/net/icmp\"\nvar _ = icmp.ListenPacket\n", 1},
144			{"dial.go", "package x\nimport \"net\"\nfunc f() { _, _ = net.Dial(\"tcp\", \"a:1\") }\n", 1},
145			{"lookup.go", "package x\nimport \"net\"\nfunc f() { _, _ = net.LookupHost(\"a\") }\n", 1},
146			{"dot.go", "package x\nimport . \"net\"\nvar _ = Interfaces\n", 1},
147			{"ifaces.go", "package x\nimport \"net\"\nvar _ = net.Interfaces\n", 0},
148			{"clean.go", "package x\nimport \"os\"\n// net.Dial in a comment\nvar _ = os.ReadFile\n", 0},
149		} {
150			ff, err := scan(token.NewFileSet(), c.name, c.src)
151			if err != nil {
152				t.Fatalf("%s: %v", c.name, err)
153			}
154			if len(ff.offences) != c.want {
155				t.Errorf("%s: got %v, want %d offences", c.name, ff.offences, c.want)
156			}
157		}
158	
159		const consts = "var a, b, c = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\", \"--networking-mode\"\n"
160		good := "package x\nimport \"os/exec\"\nvar _ = exec.CommandContext\n" + consts
161		ff, err := scan(token.NewFileSet(), wslinfoFile, good)
162		if err != nil {
163			t.Fatal(err)
164		}
165		if o := wslinfoOffences(ff); len(o) != 0 {
166			t.Errorf("good wslinfo.go flagged: %v", o)
167		}
168		for name, src := range map[string]string{
169			"lookpath":  "package x\nimport \"os/exec\"\nvar _ = exec.LookPath\n" + consts,
170			"bare name": "package x\nimport \"os/exec\"\nvar a, c = \"wslinfo\", \"--networking-mode\"\n",
171			"extra":     "package x\nimport \"os/exec\"\nvar a, b, d, c = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\", \"/bin/sh\", \"--networking-mode\"\n",
172			"order":     "package x\nimport \"os/exec\"\nvar a, b, c = \"/usr/sbin/wslinfo\", \"/usr/bin/wslinfo\", \"--networking-mode\"\n",
173			"no arg":    "package x\nimport \"os/exec\"\nvar a, b = \"/usr/bin/wslinfo\", \"/usr/sbin/wslinfo\"\n",
174			"path":      "package x\nimport \"os/exec\"\n" + consts + "var p = \"PATH\"\n",
175			"no exec":   "package x\n" + consts,
176		} {
177			ff, err := scan(token.NewFileSet(), wslinfoFile, src)
178			if err != nil {
179				t.Fatal(err)
180			}
181			if len(wslinfoOffences(ff)) == 0 {
182				t.Errorf("wslinfo.go variant %q not flagged", name)
183			}
184		}
185	}
186	
187	func TestPackageSourceGuard(t *testing.T) {
188		entries, err := os.ReadDir(".")
189		if err != nil {
190			t.Fatal(err)
191		}
192		var names []string
193		for _, e := range entries {
194			n := e.Name()
195			if !e.IsDir() && strings.HasSuffix(n, ".go") && !strings.HasSuffix(n, "_test.go") {
196				names = append(names, n)
197			}
198		}
199		sort.Strings(names)
200		if len(names) == 0 {
201			t.Fatal("the scan saw no Go file: the guard would pass vacuously")
202		}
203		fset := token.NewFileSet()
204		for _, n := range names {
205			src, err := os.ReadFile(n)
206			if err != nil {
207				t.Fatal(err)
208			}
209			ff, err := scan(fset, n, src)
210			if err != nil {
211				t.Errorf("%s: %v", n, err)
212				continue
213			}
214			for _, o := range ff.offences {
215				t.Error(o)
216			}
217			if n == wslinfoFile {
218				for _, o := range wslinfoOffences(ff) {
219					t.Error(o)
220				}
221				continue
222			}
223			if ff.importsPath("os/exec") || ff.importsPath("golang.org/x/sys/execabs") {
224				t.Errorf("%s: imports os/exec; only %s may start a process", n, wslinfoFile)
225			}
226		}
227	}
